    6334: {'title': 'Attend Yoga Class', 'description': '1. Sign up for class 2. Prepare mat and attire 3. Attend session', 'due_date': None, 'duration': 25.0, 'duration_unit': 'minutes', 'order_index': 0, 'priority': 'low'},
    6340: {'title': 'Clean the Car', 'description': '1. Wash exterior 2. Vacuum interior 3. Polish surfaces', 'due_date': None, 'duration': 40.0, 'duration_unit': 'minutes', 'order_index': 6, 'priority': 'low'},
    6341: {'title': 'Research DIY Projects', 'description': '1. Browse ideas 2. Gather materials 3. Start a project', 'due_date': None, 'duration': 50.0, 'duration_unit': 'minutes', 'order_index': 7, 'priority': 'low'},
    6335: {'title': 'Update Emergency Kit', 'description': '1. Check supplies 2. Replace expired items 3. Restock essentials', 'due_date': None, 'duration': 55.0, 'duration_unit': 'minutes', 'order_index': 1, 'priority': 'low'},
    6342: {'title': 'Plan Date Night', 'description': '1. Choose activity 2. Make reservations 3. Prepare for the evening', 'due_date': None, 'duration': 1.0, 'duration_unit': 'hours', 'order_index': 8, 'priority': 'low'}
}

new_to_original = {6365:6337, 6366:6334, 6367:6340, 6368:6341, 6369:6335, 6370:6342}

# Build a dict of new tasks from the fetched today_tasks
new_tasks = {}
for task in today_tasks['no_section_tasks']:
    if task['task_id'] in new_to_original:
        new_tasks[task['task_id']] = task

# Compare each
mismatches = []
for new_id, orig_id in new_to_original.items():
    orig = original_details[orig_id]
    new = new_tasks.get(new_id)
    if not new:
        mismatches.append(f"New task {new_id} not found")
        continue
    # Compare fields
    for field in ['title', 'description', 'due_date', 'duration', 'duration_unit', 'order_index', 'priority']:
        if new.get(field) != orig[field]:
            mismatches.append(f"Task {new_id} field {field}: expected {orig[field]}, got {new.get(field)}")

if mismatches:
    print("MISMATCHES:", mismatches)
else:
    print("All moved tasks match original details exactly.")

